const $=id=>document.getElementById(id),canvas=$('forest');let renderer;
try{renderer=new T.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true})}catch{$('error').hidden=false;throw new Error('WebGL unavailable')}
renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.04;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene(),camera=new T.PerspectiveCamera(64,1,.1,220);scene.fog=new T.FogExp2('#b4a080',.024);
const sun=new T.DirectionalLight('#ffe0a6',3.4);sun.position.set(-28,37,32);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=sun.shadow.camera.bottom=-52;sun.shadow.camera.right=sun.shadow.camera.top=52;sun.shadow.camera.far=140;sun.shadow.normalBias=.035;scene.add(sun);scene.add(sun.target);
const ambient=new T.HemisphereLight('#c8b895','#263f37',1.9);scene.add(ambient);
const skyUniforms={zenith:{value:new T.Color('#738e8d')},horizon:{value:new T.Color('#d3b388')},sunDirection:{value:new T.Vector3(-.35,.3,.85).normalize()},sunColor:{value:new T.Color('#ffe2a0')}};
const sky=new T.Mesh(new T.SphereGeometry(190,32,16),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,uniforms:skyUniforms,vertexShader:'varying vec3 direction;void main(){direction=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 direction;uniform vec3 zenith;uniform vec3 horizon;uniform vec3 sunDirection;uniform vec3 sunColor;void main(){vec3 d=normalize(direction);float h=pow(max(d.y,0.),.6);vec3 c=mix(horizon,zenith,h);float angle=max(dot(d,sunDirection),0.);c+=sunColor*(pow(angle,200.)*.42+pow(angle,1400.)*1.2);gl_FragColor=vec4(c,1.);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'}));scene.add(sky);
