// Distant mountain silhouettes stay in perspective behind the actual walkable forest.
for(let layer=0;layer<3;layer++){const geometry=new T.PlaneGeometry(240,120,100,1);const p=geometry.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i);p.setY(i,p.getY(i)>0?10+Math.sin(x*.055+layer)*10+Math.sin(x*.11+2)*6:-20);p.setZ(i,0);}geometry.computeVertexNormals();const ridge=new T.Mesh(geometry,new T.MeshBasicMaterial({color:['#6e8580','#849388','#a6a68c'][layer],side:T.DoubleSide,fog:true}));ridge.position.set(0,0,85+layer*18);scene.add(ridge);}
const state={x:trailX(-33),z:-33,yaw:-.12,pitch:.04,started:false,auto:false,mode:'sunset',time:0,sound:false,clean:false},keys=new Set();let drag=null,last=performance.now(),transition=null,uiClock=0,stage='',audioGraph=null,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const thoughts={trail:'늦은 빛이 나무 사이에 머문다.<br>오늘은 조금 느리게 걸어도 괜찮다.',river:'다리 아래로 하루가 흘러간다.<br>물소리만 잠시 들어본다.',lookout:'숲 너머에 아직 빛이 남아 있다.<br>돌아갈 길은, 조금 뒤에 생각한다.'};
const modes={sunset:{fog:'#b4a080',density:.024,sun:'#ffdb9d',strength:3.4,sky:'#718886',horizon:'#d3a976',ground:'#273c32',zenith:'#cab78c',sunPos:[-28,37,32],sunDir:[-.35,.3,.85],exposure:1.04},dawn:{fog:'#a3b3ad',density:.035,sun:'#eadfbc',strength:2.45,sky:'#5b8592',horizon:'#c0c5ac',ground:'#293f3c',zenith:'#b7ced1',sunPos:[28,40,24],sunDir:[.45,.27,.8],exposure:1.03},blue:{fog:'#415f6a',density:.029,sun:'#93b7d0',strength:.7,sky:'#142c45',horizon:'#506d73',ground:'#122b31',zenith:'#73949e',sunPos:[-22,45,32],sunDir:[-.2,.6,.7],exposure:.93}};
function applyMode(mode){state.mode=mode;const m=modes[mode];scene.fog.color.set(m.fog);scene.fog.density=m.density;sun.color.set(m.sun);sun.intensity=m.strength;sun.position.set(...m.sunPos);ambient.color.set(m.zenith);ambient.groundColor.set(m.ground);ambient.intensity=mode==='blue'?1.2:1.9;skyUniforms.zenith.value.set(m.sky);skyUniforms.horizon.value.set(m.horizon);skyUniforms.sunColor.value.set(m.sun);skyUniforms.sunDirection.value.set(...m.sunDir).normalize();renderer.toneMappingExposure=m.exposure;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('status').textContent={sunset:'일몰의 따뜻한 빛이 숲에 머뭅니다.',dawn:'새벽 안개가 숲길을 감쌉니다.',blue:'푸른 밤. 강가의 작은 불빛이 켜집니다.'}[mode];}
function resize(){const r=canvas.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio||1,r.width<700?1.4:1.7));renderer.setSize(r.width,r.height,false);}new ResizeObserver(resize).observe(canvas);resize();
function cancelTransition(){transition=null;$('sceneFade').style.opacity='0';}
function stopAuto(){state.auto=false;$('auto').setAttribute('aria-pressed','false');$('auto').innerHTML='천천히 자동 산책 <span>→</span>';}
function start(){state.started=true;document.body.classList.add('started');$('journey').hidden=false;$('status').textContent=innerWidth<700?'화면을 드래그해 둘러보고 화살표를 누르고 걸어보세요.':'드래그로 시선 이동 · W A S D / 방향키로 걷기';}
function updateStage(){const next=state.z<5?'trail':state.z<23?'river':'lookout';if(stage!==next){stage=next;const i=destinations.findIndex(p=>p.id===stage);$('chapter').textContent=String(i+1).padStart(2,'0')+' / '+destinations[i].label;$('thought').innerHTML=thoughts[stage];document.querySelectorAll('[data-place]').forEach(b=>b.setAttribute('aria-current',b.dataset.place===stage?'location':'false'));}const bearing=Math.round((state.yaw*180/Math.PI+360)%360);$('bearing').textContent=bearing<45||bearing>315?'N':bearing<135?'W':bearing<225?'S':'E';$('coordinate').textContent=stage==='trail'?'FOREST TRAIL':stage==='river'?'RIVER CROSSING':'LAST LIGHT';}
function moveTo(id){start();stopAuto();keys.clear();drag=null;const d=destinations.find(v=>v.id===id);transition={start:performance.now(),from:{x:state.x,z:state.z,yaw:state.yaw,pitch:state.pitch},to:d};$('status').textContent=d.label+'의 빛을 향해 이동합니다.';}
function update(ms){requestAnimationFrame(update);const dt=Math.min(.04,(ms-last)/1000);last=ms;state.time+=dt;let moved=false;
 if(transition){const p=Math.min(1,(ms-transition.start)/(reduced?1:1100));$('sceneFade').style.opacity=String(Math.sin(p*Math.PI));if(p>=.5&&!transition.moved){const b=transition.to;state.x=b.x;state.z=b.z;state.yaw=b.yaw;state.pitch=b.pitch;transition.moved=true;}if(p===1)cancelTransition();}
 else if(state.started){let dx=0,dz=0;const forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),right=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0);if(forward||right){stopAuto();const len=Math.hypot(forward,right),speed=2.6*dt;dx=(-Math.sin(state.yaw)*forward+Math.cos(state.yaw)*right)/len*speed;dz=(Math.cos(state.yaw)*forward+Math.sin(state.yaw)*right)/len*speed;}
  if(state.auto){const targetZ=Math.min(44,state.z+2),targetX=trailX(targetZ);state.yaw=T.MathUtils.lerp(state.yaw,-Math.atan2(targetX-state.x,targetZ-state.z),Math.min(1,dt*2));state.pitch=T.MathUtils.lerp(state.pitch,.025,dt);dx=-Math.sin(state.yaw)*1.9*dt;dz=Math.cos(state.yaw)*1.9*dt;if(state.z>=43.9){stopAuto();$('status').textContent='전망대에 도착했어요. 숲 너머의 빛을 잠시 바라보세요.';}}
  if(dx||dz){const p=stepWalker(state,dx,dz,world.colliders);state.x=p.x;state.z=p.z;moved=true;}}
 const eye=walkHeight(state.x,state.z)+1.68,bob=moved&&!reduced?Math.sin(state.time*8)*.025:0;camera.position.set(state.x,eye+bob,state.z);camera.rotation.order='YXZ';camera.rotation.set(state.pitch,Math.PI-state.yaw,0);sky.position.copy(camera.position);world.update(reduced?0:state.time,state.mode);if(!state.started&&!drag&&!reduced)camera.rotation.y+=Math.sin(state.time*.12)*.025;
 uiClock+=dt;if(uiClock>.2){uiClock=0;updateStage();canvas.dataset.position=[state.x,state.z].map(v=>v.toFixed(2)).join(',');canvas.dataset.yaw=state.yaw.toFixed(3);canvas.dataset.mode=state.mode;canvas.dataset.auto=String(state.auto);canvas.dataset.frames=String(renderer.info.render.frame);canvas.dataset.drawCalls=String(renderer.info.render.calls);}renderer.render(scene,camera);
}applyMode('sunset');requestAnimationFrame(update);$('status').textContent='숲이 준비됐어요. 드래그해서 둘러보세요.';
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;stopAuto();cancelTransition();drag={x:e.clientX,y:e.clientY,yaw:state.yaw,pitch:state.pitch};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;state.yaw=drag.yaw-(e.clientX-drag.x)*.003;state.pitch=clamp(drag.pitch-(e.clientY-drag.y)*.0025,-.58,.58);});const release=()=>drag=null;canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
const codes=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];document.addEventListener('keydown',e=>{if($('helpDialog').open)return;if(codes.includes(e.code)){e.preventDefault();start();cancelTransition();keys.add(e.code);}});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();drag=null;});
const moveCodes={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'};document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();start();cancelTransition();stopAuto();keys.add(moveCodes[b.dataset.move]);b.setPointerCapture(e.pointerId)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(moveCodes[b.dataset.move]));});
$('enter').onclick=start;document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>moveTo(b.dataset.place));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>applyMode(b.dataset.mode));$('auto').onclick=()=>{start();cancelTransition();if(state.auto){stopAuto();return}if(state.z>=43.8){state.x=trailX(-33);state.z=-33;}state.auto=true;$('auto').setAttribute('aria-pressed','true');$('auto').innerHTML='산책 잠시 멈추기 <span>Ⅱ</span>';$('status').textContent='숲길을 따라 천천히 걷고 있어요. 직접 움직이면 산책이 멈춥니다.';};
$('hide').onclick=()=>{state.clean=true;$('hide').setAttribute('aria-pressed','true');document.body.classList.add('clean');$('restore').hidden=false;};$('restore').onclick=()=>{state.clean=false;$('hide').setAttribute('aria-pressed','false');document.body.classList.remove('clean');$('restore').hidden=true;};$('help').onclick=()=>{keys.clear();stopAuto();$('helpDialog').showModal();};$('closeHelp').onclick=()=>$('helpDialog').close();
function setupAudio(){const context=new (window.AudioContext||window.webkitAudioContext)(),master=context.createGain();master.gain.value=0;master.connect(context.destination);const buffer=context.createBuffer(1,context.sampleRate*3,context.sampleRate),data=buffer.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){brown=(brown+(Math.random()*2-1)*.02)/1.02;data[i]=brown*3.5;}const wind=context.createBufferSource();wind.buffer=buffer;wind.loop=true;const filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=420;wind.connect(filter);filter.connect(master);wind.start();const river=context.createBufferSource();river.buffer=buffer;river.loop=true;const high=context.createBiquadFilter();high.type='bandpass';high.frequency.value=1000;high.Q.value=.3;const gain=context.createGain();gain.gain.value=.3;river.connect(high);high.connect(gain);gain.connect(master);river.start();return {context,master,gain};}
$('sound').onclick=()=>{try{audioGraph||=setupAudio();audioGraph.context.resume();state.sound=!state.sound;audioGraph.master.gain.setTargetAtTime(state.sound?.14:0,audioGraph.context.currentTime,.4);$('sound').setAttribute('aria-pressed',String(state.sound));$('sound').setAttribute('aria-label',state.sound?'숲 소리 끄기':'숲 소리 켜기');$('sound').querySelector('span').textContent=state.sound?'소리 켬':'소리 끔';}catch{$('status').textContent='브라우저에서 소리를 재생할 수 없어요.';}};
